"""Numerical routines for the Maxwell-Bloch model used by the GUI.This module builds simulation grids, prepares initial and boundary conditions,and advances the coupled field and material equations."""from __future__ import annotationsimport numpy as npfrom numba import njitfrom solver.profiles import evaluate_pulse_profile, step_func# -----------------------------------------------------------------------------# Helper Functions# -----------------------------------------------------------------------------@njit(inline="always", nogil=True, cache=True)def build_grids(t_max: float, nt: int, nz: int):    """Build the one-dimensional temporal and spatial grids used by the solver.    Args:        t_max: Maximum simulation time.        nt: Number of time-grid points.        nz: Number of spatial-grid points.    Returns:        Tuple ``(t, dt, z, dz)`` containing the time array, time step, spatial        array, and spatial step.    """    t = np.linspace(0.0, t_max, nt)    dt = t_max / (nt - 1)    z = np.linspace(0.0, 1.0, nz)    dz = 1.0 / (nz - 1)    return t, dt, z, dz# -----------------------------------------------------------------------------# Initial conditions# -----------------------------------------------------------------------------@njit(inline="always", nogil=True, cache=True)def compute_initial_conditions(z, w0, R0):    """Construct the initial state arrays for the Maxwell-Bloch system.    Args:        z: Spatial grid array used only to determine the output size.        w0: Initial population value.        R0: Initial coherence value.    Returns:        Tuple ``(w, R)`` containing arrays filled with the requested initial        population and coherence values.    """    w = np.full_like(z, w0, dtype=np.float64)    R = np.full_like(z, R0, dtype=np.float64)    return w, R# -----------------------------------------------------------------------------# Maxwell-Bloch Equations# -----------------------------------------------------------------------------@njit(inline="always", nogil=True, cache=True)def _dw_dt(w, R, A, kw, kR, w0, inv_t1, lambda_n):    """Evaluate the population derivative for one solver stage.    Args:        w: Current population value.        R: Current coherence value.        A: Current field value.        kw: Runge-Kutta population increment.        kR: Runge-Kutta coherence increment.        w0: Reference initial population.        inv_t1: Inverse longitudinal relaxation time.        lambda_n: Pump term.    Returns:        Population derivative for the current stage.    """    return A * (R + kR) - (w + kw - w0) * inv_t1 + lambda_n@njit(inline="always", nogil=True, cache=True)def _dR_dt(w, R, A, kw, kR, R0, inv_t2):    """Evaluate the coherence derivative for one solver stage.    Args:        w: Current population value.        R: Current coherence value.        A: Current field value.        kw: Runge-Kutta population increment.        kR: Runge-Kutta coherence increment.        R0: Reference initial coherence.        inv_t2: Inverse transverse relaxation time.    Returns:        Coherence derivative for the current stage.    """    return -A * (w + kw) - (R + kR - R0) * inv_t2@njit(inline="always", nogil=True, cache=True)def _dA_dz(eta, R, dz):    """Evaluate the field increment along the propagation direction.    Args:        eta: Coupling coefficient.        R: Current coherence value.        dz: Spatial step size.    Returns:        Field increment across one spatial step.    """    return -eta * R * dz@njit(inline="always", nogil=True, cache=True)def _rk4_dn_dR(        w,        R,        A,        inv_t1,        inv_t2,        w0,        R0,        lambda_n,        dt,        half_dt,        dt6,):    """Advance population and coherence with one fourth-order Runge-Kutta step.    Args:        w: Current population value.        R: Current coherence value.        A: Current field value.        inv_t1: Inverse longitudinal relaxation time.        inv_t2: Inverse transverse relaxation time.        w0: Reference initial population.        R0: Reference initial coherence.        lambda_n: Pump term.        dt: Full time step.        half_dt: Half time step.        dt6: One sixth of the time step.    Returns:        Tuple ``(dw, dR)`` containing the Runge-Kutta increments for population        and coherence.    """    kw_1 = _dw_dt(w, R, A, 0, 0, w0, inv_t1, lambda_n)    kR_1 = _dR_dt(w, R, A, 0, 0, R0, inv_t2)    kw_2 = _dw_dt(w, R, A, half_dt * kw_1, half_dt * kR_1, w0, inv_t1, lambda_n)    kR_2 = _dR_dt(w, R, A, half_dt * kw_1, half_dt * kR_1, R0, inv_t2)    kw_3 = _dw_dt(w, R, A, half_dt * kw_2, half_dt * kR_2, w0, inv_t1, lambda_n)    kR_3 = _dR_dt(w, R, A, half_dt * kw_2, half_dt * kR_2, R0, inv_t2)    kw_4 = _dw_dt(w, R, A, dt * kw_3, dt * kR_3, w0, inv_t1, lambda_n)    kR_4 = _dR_dt(w, R, A, dt * kw_3, dt * kR_3, R0, inv_t2)    dw = dt6 * (kw_1 + 2.0 * kw_2 + 2.0 * kw_3 + kw_4)    dR = dt6 * (kR_1 + 2.0 * kR_2 + 2.0 * kR_3 + kR_4)    return dw, dR# -----------------------------------------------------------------------------# Runge-Kutta PDE Solver# -----------------------------------------------------------------------------@njit(nogil=True, cache=True)def _runge_kutta_solver(        t,        dt,        z,        dz,        n_z_planes,        w0,        R0,        A0,        lambda_n,        t1,        t2,        eta,):    """Advance the coupled Maxwell-Bloch system across the simulation grid.    Args:        t: Time grid.        dt: Time step size.        z: Spatial grid.        dz: Spatial step size.        n_z_planes: Number of spatial planes to store in the output.        w0: Initial population profile along ``z``; also the equilibrium            value that ``w`` relaxes toward.        R0: Initial coherence profile along ``z``; also the equilibrium            value that ``R`` relaxes toward.        A0: Boundary-driving field on the time grid.        lambda_n: Pump profile on the time grid.        t1: Longitudinal relaxation time on the time grid (must be > 0).        t2: Transverse relaxation time on the time grid (must be > 0).        eta: Coupling coefficient.    Returns:        Tuple ``(w_result, I_result)`` containing sampled population values and        field intensities on the requested spatial planes.    """    nt = len(t)    nz = len(z)    z_planes = np.linspace(0.0, 1.0, n_z_planes)    z_plane_indices = np.rint(z_planes * (nz - 1)).astype(np.int64)    inv_t1 = 1.0 / t1    inv_t2 = 1.0 / t2    half_dt = 0.5 * dt    dt6 = dt / 6.0    w_old = np.empty(nt, dtype=np.float64)    R_old = np.empty(nt, dtype=np.float64)    A_old = np.empty(nt, dtype=np.float64)    w_new = np.empty_like(w_old)    R_new = np.empty_like(R_old)    A_new = np.empty_like(A_old)    w_result = np.empty((n_z_planes, nt), dtype=np.float64)    I_result = np.empty((n_z_planes, nt), dtype=np.float64)    w_old[0], R_old[0] = w0[0], R0[0]    A_old[0] = A0[0]    w0_0 = w0[0]    R0_0 = R0[0]    for t_idx in range(1, nt):        dw, dR = _rk4_dn_dR(            w_old[t_idx - 1],            R_old[t_idx - 1],            A_old[t_idx - 1],            inv_t1[t_idx - 1],            inv_t2[t_idx - 1],            w0_0,            R0_0,            lambda_n[t_idx - 1],            dt,            half_dt,            dt6,        )        w_old[t_idx] = w_old[t_idx - 1] + dw        R_old[t_idx] = R_old[t_idx - 1] + dR        A_old[t_idx] = A0[t_idx]    w_result[0, :] = w_old    I_result[0, :] = A_old * A_old    i = 1    for z_idx in range(1, nz):        w_new[0], R_new[0] = w0[z_idx], R0[z_idx]        A_new[0] = A_old[0] + _dA_dz(eta, R_old[0], dz)        w0_i = w0[z_idx]        R0_i = R0[z_idx]        for t_idx in range(1, nt):            dw, dR = _rk4_dn_dR(                w_new[t_idx - 1],                R_new[t_idx - 1],                A_new[t_idx - 1],                inv_t1[t_idx - 1],                inv_t2[t_idx - 1],                w0_i,                R0_i,                lambda_n[t_idx - 1],                dt,                half_dt,                dt6,            )            w_new[t_idx] = w_new[t_idx - 1] + dw            R_new[t_idx] = R_new[t_idx - 1] + dR            A_new[t_idx] = A_old[t_idx] + _dA_dz(eta, R_old[t_idx], dz)        if i < n_z_planes and z_plane_indices[i] == z_idx:            w_result[i, :] = w_new            I_result[i, :] = A_new * A_new            i += 1        w_old, w_new = w_new, w_old        R_old, R_new = R_new, R_old        A_old, A_new = A_new, A_old    return w_result, I_result# -----------------------------------------------------------------------------# MBE Solver Interface# -----------------------------------------------------------------------------def solve_maxwell_bloch(params):    """Solve the configured Maxwell-Bloch problem and return sampled outputs.    Args:        params: Parameter mapping with grid, sample, pump, dynamics (T1, T2),            initial-condition, boundary-condition, and slicing settings.            T1 and T2 may each be a constant or a step-profile mapping.    Returns:        Mapping with keys:            ``time``: time grid,            ``intensity``: intensity samples,            ``w``: population inversion samples,            ``lambda_n``: pump profile,            ``A0``: boundary-driving field,            ``t1``, ``t2``: relaxation times evaluated on the time grid.    """    t, dt, z, dz = build_grids(        nt=params["solve.grid.nt"],        nz=params["solve.grid.nz"],        t_max=params["solve.grid.t_max"],    )    lambda_n = (evaluate_pulse_profile(t, params.get("solve.pump.pulse1", {})) +                evaluate_pulse_profile(t, params.get("solve.pump.pulse2", {})) +                evaluate_pulse_profile(t, params.get("solve.pump.pulse3", {}))                )    if params["solve.ics"]["use_theta0"]:        theta0 = params["solve.sample"]["theta0"]        w0, R0 = compute_initial_conditions(z, w0=np.cos(theta0), R0=np.sin(theta0))    else:        w0, R0 = compute_initial_conditions(z, w0=params["solve.ics"]["w0"], R0=params["solve.ics"]["R0"])    t1 = step_func(value=params["solve.t1"], x=t)    t2 = step_func(value=params["solve.t2"], x=t)    n_z_planes = min(params["slice.z"]["arr_length"], params["solve.grid.nz"])    A0 = evaluate_pulse_profile(t, params["solve.bcs"])    w, I = _runge_kutta_solver(        t=t, dt=dt, z=z, dz=dz, n_z_planes=n_z_planes,        w0=w0, R0=R0, A0=A0, lambda_n=lambda_n,        t1=t1, t2=t2, eta=params["solve.sample"]["eta"],    )    return {        "time": t,        "intensity": I,        "w": w,        "lambda_n": lambda_n,        "A0": A0,        "t1": t1,        "t2": t2,    }